const perintisPeople = `-- name: PerintisPeople :many

SELECT
  u.id AS user_id,
  u.email,
  u.account_status,
  COALESCE(p.name, split_part(COALESCE(u.email, ''), '@', 1))::text AS name,
  p.gender,
  p.whatsapp,
  p.instagram,
  p.linkedin,
  p.university_id,
  un.name AS university,
  p.major,
  p.intake_year,
  COALESCE(p.level, 0)::int AS level,
  COALESCE(p.badges, '[]'::jsonb) AS badges,
  c.name AS city,
  pr.name AS province
FROM public_users u
LEFT JOIN profiles p ON p.user_id = u.id
LEFT JOIN universities un ON un.id = p.university_id
LEFT JOIN cities c ON c.id = p.city_id
LEFT JOIN provinces pr ON pr.id = p.province_id
WHERE u.id = ANY($1::int[])
ORDER BY u.id
`

